<?php declare(strict_types=1); $title = 'Existencias por lote'; ?>
<section>
    <div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold uppercase tracking-wide text-emerald-700">Inventario</p><h1 class="mt-1 text-3xl font-bold tracking-tight text-slate-900">Existencias por lote</h1><p class="mt-2 text-sm text-slate-600">Consulta saldos por lote y registra ajustes físicos con su motivo.</p></div></div>
    <?php if ($success): ?><div role="status" class="mb-5 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-900"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div role="alert" class="mb-5 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800"><?= e($error) ?></div><?php endif; ?>
    <form method="get" action="<?= e($baseUrl) ?>/existencias" class="mb-5 flex gap-3 rounded-xl border border-slate-200 bg-white p-4"><input name="q" value="<?= e($search) ?>" maxlength="100" placeholder="Buscar producto, código o lote" class="min-h-11 flex-1 rounded-lg border border-slate-300 px-3 text-sm"><button class="rounded-lg border border-slate-300 px-4 text-sm font-semibold">Buscar</button></form>
    <div class="mb-8 overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200 text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-600"><tr><?php foreach (['Producto', 'Lote', 'Vencimiento', 'Stock actual', 'Compra origen', 'Estado', ''] as $label): ?><th class="px-4 py-3"><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100">
    <?php if (!$balances): ?><tr><td colspan="7" class="px-4 py-10 text-center text-slate-500">No se encontraron lotes.</td></tr><?php endif; ?>
    <?php foreach ($balances as $row): $expired=(int)$row['vencido']===1; ?><tr class="<?= $expired?'bg-red-50/50':'' ?>"><td class="px-4 py-3"><strong><?= e($row['producto']) ?></strong><div class="text-xs text-slate-500"><?= e($row['codigo']) ?> · <?= e($row['unidad_medida']) ?><?= !(int)$row['producto_activo']?' · Producto inactivo':'' ?></div></td><td class="px-4 py-3 font-medium"><?= e($row['codigo_lote']) ?></td><td class="px-4 py-3"><?= e($row['fecha_vencimiento'] ? date('d/m/Y',strtotime($row['fecha_vencimiento'])) : 'Sin vencimiento') ?></td><td class="px-4 py-3 font-semibold"><?= e(number_format((float)$row['cantidad_disponible'],3)) ?> <?= e($row['unidad_medida']) ?></td><td class="px-4 py-3"><a class="text-emerald-800 hover:underline" href="<?= e($baseUrl) ?>/compras/detalle?id=<?= e($row['compra_id']) ?>">Compra #<?= e($row['compra_id']) ?></a></td><td class="px-4 py-3"><span class="rounded-full px-2 py-1 text-xs font-semibold <?= $expired?'bg-red-100 text-red-800':((float)$row['cantidad_disponible']>0?'bg-emerald-100 text-emerald-800':'bg-slate-200 text-slate-700') ?>"><?= $expired?'Vencido':((float)$row['cantidad_disponible']>0?'Disponible':'Agotado') ?></span></td><td class="px-4 py-3"><?php if (can('existencias.ajustar')): ?><a class="font-semibold text-emerald-800 hover:underline" href="<?= e($baseUrl) ?>/existencias/ajustar?id=<?= e($row['lote_id']) ?>">Ajustar</a><?php endif; ?></td></tr><?php endforeach; ?>
    </tbody></table></div>
    <div class="mb-4 flex items-end justify-between gap-4"><div><h2 class="text-xl font-bold text-slate-900">Movimientos recientes</h2><p class="mt-1 text-sm text-slate-600">Últimos 50 movimientos de compras, ventas y ajustes.</p></div><?php if (can('movimientos.ver')): ?><a href="<?= e($baseUrl) ?>/movimientos" class="text-sm font-semibold text-emerald-800 hover:underline">Ver historial completo →</a><?php endif; ?></div>
    <div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200 text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-600"><tr><?php foreach (['Fecha', 'Producto / lote', 'Tipo', 'Variación', 'Motivo', 'Usuario', 'Referencia'] as $label): ?><th class="px-4 py-3"><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100">
    <?php if (!$movements): ?><tr><td colspan="7" class="px-4 py-8 text-center text-slate-500">Aún no hay movimientos de inventario.</td></tr><?php endif; ?>
    <?php foreach ($movements as $movement): $typeLabels=['compra'=>'Compra','venta'=>'Venta','ajuste_entrada'=>'Ajuste de entrada','ajuste_salida'=>'Ajuste de salida','anulacion'=>'Anulación']; ?><tr><td class="whitespace-nowrap px-4 py-3"><?= e(date('d/m/Y H:i',strtotime($movement['creado_en']))) ?></td><td class="px-4 py-3"><strong><?= e($movement['producto']) ?></strong><div class="text-xs text-slate-500"><?= e($movement['codigo']) ?> · Lote <?= e($movement['codigo_lote'] ?? '—') ?></div></td><td class="px-4 py-3"><?= e($typeLabels[$movement['tipo']] ?? $movement['tipo']) ?></td><td class="whitespace-nowrap px-4 py-3 font-semibold <?= (float)$movement['cantidad_delta']<0?'text-red-700':'text-emerald-800' ?>"><?= (float)$movement['cantidad_delta']>0?'+':'' ?><?= e(number_format((float)$movement['cantidad_delta'],3)) ?></td><td class="max-w-xs px-4 py-3"><?= e($movement['motivo'] ?: '—') ?></td><td class="px-4 py-3"><?= e($movement['usuario']) ?></td><td class="px-4 py-3"><?php if ($movement['compra_id']): ?><a class="text-emerald-800 hover:underline" href="<?= e($baseUrl) ?>/compras/detalle?id=<?= e($movement['compra_id']) ?>">Compra #<?= e($movement['compra_id']) ?></a><?php elseif ($movement['venta_id']): ?><a class="text-emerald-800 hover:underline" href="<?= e($baseUrl) ?>/ventas/detalle?id=<?= e($movement['venta_id']) ?>">Venta #<?= e($movement['venta_id']) ?></a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
    </tbody></table></div>
</section>
